import { FC } from 'react';

type ProgressType = 'line' | 'circle';
type ProgressStatus = 'normal' | 'success' | 'error';
interface ProgressProps {
    /** 进度百分比 */
    percent: number;
    /** 类型 */
    type?: ProgressType;
    /** 状态 */
    status?: ProgressStatus;
    /** 是否显示进度文字 */
    showText?: boolean;
    /** 自定义文字格式 */
    format?: (percent: number) => string;
    /** 轨道颜色 */
    trackColor?: string;
    /** 填充颜色 */
    fillColor?: string;
    /** 线条宽度 (rpx) */
    strokeWidth?: number;
    /** 圆形直径 (rpx)，仅 circle 类型有效 */
    size?: number;
    /** 自定义类名 */
    className?: string;
}

declare const Progress: FC<ProgressProps>;

export { Progress, Progress as default };
export type { ProgressProps, ProgressStatus, ProgressType };
